"""Who holds which book, on disk so separate `shelf` processes agree.

The loans table keys on title, so the database itself guarantees one holder
per book: of two racing lends, exactly one INSERT succeeds.
"""
import os
import sqlite3


class AlreadyLent(Exception):
    def __init__(self, title, member):
        super().__init__("%s is already lent to %s" % (title, member))
        self.member = member


class NotLent(Exception):
    def __init__(self, title):
        super().__init__("%s is not lent out" % title)


def _connect():
    path = os.environ.get("SHELF_DB", "shelf.db")
    conn = sqlite3.connect(path, timeout=30, isolation_level=None)
    conn.execute(
        "CREATE TABLE IF NOT EXISTS loans"
        " (title TEXT PRIMARY KEY, member TEXT NOT NULL)"
    )
    return conn


def lend(title, member):
    conn = _connect()
    try:
        try:
            conn.execute(
                "INSERT INTO loans (title, member) VALUES (?, ?)", (title, member)
            )
        except sqlite3.IntegrityError:
            row = conn.execute(
                "SELECT member FROM loans WHERE title = ?", (title,)
            ).fetchone()
            raise AlreadyLent(title, row[0] if row else "another member")
    finally:
        conn.close()


def give_back(title):
    conn = _connect()
    try:
        if conn.execute("DELETE FROM loans WHERE title = ?", (title,)).rowcount == 0:
            raise NotLent(title)
    finally:
        conn.close()


def holder(title):
    conn = _connect()
    try:
        row = conn.execute(
            "SELECT member FROM loans WHERE title = ?", (title,)
        ).fetchone()
    finally:
        conn.close()
    return row[0] if row else None

